from pydantic import BaseModel

class ComparisonType(str, Enum):
    """Defines different ways to compare field values."""
    EXACT = "exact"  # Perfect string/value match
    FUZZY = "fuzzy"  # Approximate string matching (Levenshtein distance)
    SEMANTIC = "semantic"  # Semantic similarity (embedding-based)
    NUMERIC = "numeric"  # Numeric comparison with tolerance
    CUSTOM = "custom"  # Custom comparison function

class FieldComparisonConfig(BaseModel):
    """Configuration for comparing different field types."""

    comparison_type: ComparisonType
    similarity_threshold: float = 0.8  # Default threshold for non-exact comparisons
    numeric_tolerance: float = 0.01  # Default tolerance for numeric comparisons (1%)
    custom_comparator: Optional[Callable[[Any, Any], bool]] = None

    def is_match(self, expected: Any, predicted: Any) -> bool:
        """
        Determine if predicted value matches expected value according to config.

        Args:
            expected: The expected value
            predicted: The predicted value

        Returns:
            bool: True if values match according to comparison criteria
        """
        if expected is None and predicted is None:
            return True

        if expected is None or predicted is None:
            return False

        if self.comparison_type == ComparisonType.EXACT:
            return self._exact_match(expected, predicted)

        elif self.comparison_type == ComparisonType.FUZZY:
            return self._fuzzy_match(expected, predicted)

        elif self.comparison_type == ComparisonType.SEMANTIC:
            return self._semantic_match(expected, predicted)

        elif self.comparison_type == ComparisonType.NUMERIC:
            return self._numeric_match(expected, predicted)

        elif self.comparison_type == ComparisonType.CUSTOM and self.custom_comparator:
            return self.custom_comparator(expected, predicted)

        # Default to exact match if no valid comparison type
        return self._exact_match(expected, predicted)

    def _exact_match(self, expected: Any, predicted: Any) -> bool:
        """Check if values match exactly."""
        # Convert both to strings for more flexible comparison
        if isinstance(expected, (list, dict)) and isinstance(predicted, (list, dict)):
            # For complex objects, compare serialized versions
            import json
            return json.dumps(expected, sort_keys=True) == json.dumps(predicted, sort_keys=True)
        return str(expected).strip() == str(predicted).strip()

    def _fuzzy_match(self, expected: Any, predicted: Any) -> bool:
        """Check if string values approximately match."""
        try:
            # Import Levenshtein only when needed
            from Levenshtein import ratio

            # Convert to strings
            expected_str = str(expected).strip()
            predicted_str = str(predicted).strip()

            # Calculate similarity ratio
            similarity = ratio(expected_str, predicted_str)
            return similarity >= self.similarity_threshold
        except ImportError:
            # Fallback to exact match if Levenshtein not available

from typing import Any, Dict, List, Union, Optional, IO
from cachetools import cachedmethod
from cachetools.keys import hashkey
from operator import attrgetter
from extract_thinker.document_loader.cached_document_loader import CachedDocumentLoader
from dataclasses import dataclass

@dataclass
class DataLoaderConfig:
    """Configuration for Data loader.

    Args:
        content: Initial content (optional)
        cache_ttl: Cache time-to-live in seconds (default: 300)
        supports_vision: Whether this loader supports vision mode (default: True)
    """
    content: Optional[Any] = None
    cache_ttl: int = 300
    supports_vision: bool = True

class DocumentLoaderData(CachedDocumentLoader):
    """
    Document loader that handles pre-processed data with caching support.
    Expects data in standard format:
    [
      {
        "content": "...some text...",
        "image": None or [] or bytes
      }
    ]
    """

    def __init__(self, 
                 content: Optional[Any] = None,
                 cache_ttl: int = 300,
                 supports_vision: bool = True):
        """Initialize loader with optional content and cache settings."""
        self.config = DataLoaderConfig(
            content=content,
            cache_ttl=cache_ttl,
            supports_vision=supports_vision
        )
        super().__init__(self.config.content, self.config.cache_ttl)
        self._supports_vision = self.config.supports_vision

    def can_handle(self, source: Any) -> bool:
        """Check if we can handle this source type."""
        if isinstance(source, str):
            return True
        if hasattr(source, "read"):
            return True
        if isinstance(source, list) and all(isinstance(item, dict) for item in source):
            return True
        if isinstance(source, dict):
            return True
        return False

    @cachedmethod(cache=attrgetter('cache'), 
                  key=lambda self, source: hashkey(
                      source if isinstance(source, str)
                      else source.getvalue() if hasattr(source, 'getvalue')
                      else str(source),
                      self.vision_mode))
    def load(self, source: Union[str, IO, List[Dict[str, Any]]]) -> List[Dict[str, Any]]:
        """
        Load and process content with caching support.
        Returns a list of pages in standard format.

        Args:
            source: String, IO stream, or pre-formatted list of dicts

        Returns:
            List[Dict[str, Any]]: List of pages with content and image
        """
        if not self.can_handle(source):
            raise ValueError("Can only handle str, readable streams, or list of dicts")

        try:
            if isinstance(source, list):
                return self._validate_and_format_list(source)
            elif isinstance(source, str):
                return self._load_from_string(source)
            elif hasattr(source, "read"):
                return self._load_from_stream(source)
            elif isinstance(source, dict):
                return source

        except Exception as e:
            raise ValueError(f"Error processing content: {str(e)}")

    def _validate_and_format_list(self, data: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Validate and format a list of dictionaries."""
        formatted_pages = []
        for item in data:
            if not isinstance(item, dict):
                raise ValueError(
                    "Invalid format. Expected a list of dictionaries in format: "
                    "[{'content': 'your text here', 'image': None or [] or bytes}, ...]. "
                    f"Got item of type {type(item).__name__} instead of dict"
                )
            if "content" not in item:
                raise ValueError(
                    "Invalid format. Each dictionary must have a 'content' field. "
                    "Expected format: [{'content': 'your text here', 'image': None or [] or bytes}, ...]. "
                    f"Got keys: {list(item.keys())}"
                )

            # Preserve the original image value if present, otherwise use vision mode default
            image_value = item.get("image", [] if self.vision_mode else None)
            page = {
                "content": item["content"],
                "image": image_value
            }
            formatted_pages.append(page)
        return formatted_pages

    def _load_from_string(self, text: str) -> List[Dict[str, Any]]:
        """Process string input."""
        try:
            # Try to read as file first
            with open(text, "r", encoding="utf-8") as f:
                content = f.read()
        except (FileNotFoundError, IOError):
            # If not a file, treat as raw text
            content = text

        return [{
            "content": content,
            "image": [] if self.vision_mode else None
        }]

    def _load_from_stream(self, stream: IO) -> List[Dict[str, Any]]:
        """Process stream input."""
        try:
            content = stream.read()
            if isinstance(content, bytes):
                content = content.decode('utf-8')

            return [{
                "content": content,
                "image": [] if self.vision_mode else None
            }]
        except Exception as e:
            raise ValueError(f"Failed to read from stream: {str(e)}")

    def can_handle_vision(self, source: Union[str, IO]) -> bool:
        """Check if this loader can handle the source in vision mode."""
        return self._supports_vision and self.can_handle(source)

